\set ON_ERROR_STOP on
BEGIN;

-- This fixture is reserved for the disposable ProductionReadiness database.
-- Refuse to run anywhere else; this prevents fixed smoke identities reaching a real tenant.
DO $$
BEGIN
  IF current_setting('barbersync.environment', true) IS DISTINCT FROM 'ProductionReadiness' THEN
    RAISE EXCEPTION 'production_readiness_seed.sql requires barbersync.environment=ProductionReadiness';
  END IF;
END $$;


-- ASP.NET Core Identity PasswordHasher V3 hash for the local-only password documented in the runbook.
-- The two operational smoke roles receive the schema's explicit permissions, never an auth bypass.

UPDATE barber.products SET category_id='70000000-0000-4000-8000-000000000095',usage_type='Both',unit='Unit',reorder_point=4 WHERE id='70000000-0000-4000-8000-000000000040' AND tenant_id='70000000-0000-4000-8000-000000000001';
-- IA operacional: metadados sintéticos, sem imagens, biometria ou credenciais reais.

-- Sprint 42 governance readiness. Fixed identifiers belong exclusively to ProductionReadiness.
VALUES('42420000-0000-4000-8000-000000000001','PRODUCTION_READINESS','Production Readiness','Plano técnico para validação de release',0,0,5,25,25,500,1024,'Active') ON CONFLICT(code) DO UPDATE SET updated_at=now();
SELECT '42420000-0000-4000-8000-000000000002',t.id,'42420000-0000-4000-8000-000000000001','Trial','Monthly',now(),now()+interval '30 days' FROM barber.tenants t WHERE t.name='ProductionReadiness' ON CONFLICT(id) DO NOTHING;
SELECT c.tenant_id,c.branch_id,c.id,x.key,x.title,x.title,'Pending' FROM barber.onboarding_checklists c CROSS JOIN (VALUES('branch','Cadastrar filial'),('services','Cadastrar serviços'),('professionals','Cadastrar profissionais'),('schedule','Configurar agenda'),('cash','Configurar caixa'),('inventory','Configurar produtos e estoque'),('payments','Configurar formas de pagamento'),('permissions','Configurar permissões'),('communication','Configurar comunicação'),('ai-operations','Configurar IA Operacional (opcional)')) x(key,title) WHERE c.id='42420000-0000-4000-8000-000000000004' ON CONFLICT(checklist_id,item_key) DO NOTHING;

-- Agenda Sprint 48: cenário controlado e idempotente, exclusivo de ProductionReadiness.

-- Cliente 360 Sprint 49: prontuário e jornada controlados do cliente readiness.

COMMIT;

-- Clube & Vendas readiness: referências reais do tenant/unidade readiness; nenhuma liberação fictícia.
DO $$
DECLARE t uuid; b uuid; u uuid; c uuid; p uuid; m uuid; cy uuid; be uuid; w uuid; co uuid;
BEGIN
 SELECT tenant_id,branch_id,user_id INTO t,b,u FROM barber.governance_audit_events ORDER BY created_at LIMIT 1;
 SELECT id INTO c FROM barber.clients WHERE tenant_id=t AND branch_id=b AND deleted_at IS NULL ORDER BY created_at LIMIT 1;
 IF t IS NULL OR b IS NULL OR c IS NULL THEN RAISE NOTICE 'Club readiness skipped: tenant, branch or client unavailable'; RETURN; END IF;
 IF p IS NULL THEN SELECT id INTO p FROM barber.club_plans WHERE tenant_id=t AND branch_id=b AND name='Readiness Club Plan' LIMIT 1; END IF;
END $$;

-- Portal do Cliente: evidências determinísticas e idempotentes, vinculadas ao cliente readiness canônico.
WITH scope AS (SELECT c.tenant_id,c.branch_id,c.id client_id FROM barber.clients c WHERE c.email='client@readiness.local' ORDER BY c.created_at LIMIT 1)
SELECT '51000000-0000-4000-8000-000000000001',tenant_id,branch_id,client_id,'Email','r***@barbersync.local',encode(digest('readiness-expired-code','sha256'),'hex'),'Login','Used',now()-interval '1 hour',now()-interval '2 hours' FROM scope ON CONFLICT(id) DO NOTHING;
WITH scope AS (SELECT c.tenant_id,c.branch_id,c.id client_id FROM barber.clients c WHERE c.email='client@readiness.local' ORDER BY c.created_at LIMIT 1)
SELECT '51000000-0000-4000-8000-000000000002',tenant_id,branch_id,client_id,encode(digest('readiness-revoked-session','sha256'),'hex'),'Revoked',now()-interval '1 hour',now()-interval '1 hour' FROM scope ON CONFLICT(id) DO NOTHING;
WITH scope AS (SELECT c.tenant_id,c.branch_id,c.id client_id FROM barber.clients c WHERE c.email='client@readiness.local' ORDER BY c.created_at LIMIT 1)
SELECT '51000000-0000-4000-8000-000000000003',tenant_id,branch_id,client_id,'ReadinessChecked','Readiness','Evidência do portal sem envio externo' FROM scope ON CONFLICT(id) DO NOTHING;
WITH scope AS (SELECT c.tenant_id,c.branch_id,c.id client_id FROM barber.clients c WHERE c.email='client@readiness.local' ORDER BY c.created_at LIMIT 1)
SELECT '51000000-0000-4000-8000-000000000004',tenant_id,branch_id,client_id,'appointmentReminders','true' FROM scope ON CONFLICT(id) DO NOTHING;
WITH scope AS (SELECT c.tenant_id,c.branch_id,c.id client_id FROM barber.clients c WHERE c.email='client@readiness.local' ORDER BY c.created_at LIMIT 1)
SELECT '51000000-0000-4000-8000-000000000005',tenant_id,branch_id,client_id,'Readiness do portal','Other','Low','Resolved' FROM scope ON CONFLICT(id) DO NOTHING;
WITH scope AS (SELECT c.tenant_id,c.branch_id,c.id client_id FROM barber.clients c WHERE c.email='client@readiness.local' ORDER BY c.created_at LIMIT 1)
SELECT '51000000-0000-4000-8000-000000000006',tenant_id,branch_id,client_id,'Manual',0,'Expired',now()-interval '1 day' FROM scope ON CONFLICT(id) DO NOTHING;

