WITH scope AS (SELECT c.tenant_id,c.branch_id,c.id client_id FROM barber.clients c WHERE c.email='client@readiness.local' ORDER BY c.created_at LIMIT 1)
WITH scope AS (SELECT c.tenant_id,c.branch_id,c.id client_id FROM barber.clients c WHERE c.email='client@readiness.local' ORDER BY c.created_at LIMIT 1)

-- Marketing Studio readiness: somente dados operacionais idempotentes vinculados ao tenant/unidade readiness.
DO $$ DECLARE t uuid; b uuid; u uuid; s uuid; l uuid; c uuid; p uuid; q uuid; e uuid;
BEGIN
 SELECT id INTO t FROM barber.tenants ORDER BY created_at LIMIT 1; SELECT id INTO b FROM barber.branches WHERE tenant_id=t ORDER BY created_at LIMIT 1; SELECT id INTO u FROM barber.users WHERE tenant_id=t ORDER BY created_at LIMIT 1;
 IF t IS NULL OR b IS NULL THEN RETURN; END IF;
 SELECT id INTO s FROM barber.marketing_segments WHERE tenant_id=t AND branch_id=b AND segment_key='readiness-return-pending';
 SELECT id INTO l FROM barber.marketing_landing_pages WHERE tenant_id=t AND branch_id=b AND slug='readiness-retorno';
 SELECT id INTO p FROM barber.marketing_promo_links WHERE tenant_id=t AND branch_id=b AND public_slug='readiness-marketing';
END $$;

-- Marketplace & Parceiros readiness: registros operacionais controlados; nenhum payout é pago.
DO $$ DECLARE t uuid; b uuid; u uuid; p uuid; a uuid; l uuid; r uuid; cr uuid; sup uuid; prod uuid;
BEGIN
 SELECT id INTO t FROM barber.tenants ORDER BY created_at LIMIT 1; SELECT id INTO b FROM barber.branches WHERE tenant_id=t ORDER BY created_at LIMIT 1; SELECT id INTO u FROM barber.users WHERE tenant_id=t ORDER BY created_at LIMIT 1;
 IF t IS NULL OR b IS NULL THEN RETURN; END IF;
 SELECT id INTO sup FROM barber.suppliers WHERE tenant_id=t AND branch_id=b ORDER BY created_at LIMIT 1; SELECT id INTO prod FROM barber.products WHERE tenant_id=t AND branch_id=b ORDER BY created_at LIMIT 1;
 IF sup IS NOT NULL AND prod IS NOT NULL THEN INSERT INTO barber.partner_supplier_terms(id,tenant_id,branch_id,partner_id,supplier_id,product_id,negotiated_price,lead_time_days,minimum_order_quantity,status,created_by) VALUES('53000000-0000-4000-8000-000000000010',t,b,p,sup,prod,1,7,1,'Active',u) ON CONFLICT(id) DO NOTHING; END IF;
END $$;

-- Central de Controle: evidência determinística exclusiva do banco descartável de readiness.

-- Sprint 57: evidencias idempotentes de Catalogo & Precificacao; nenhuma venda, pagamento ou comissao paga e simulada.
DO $$ DECLARE t uuid:='70000000-0000-4000-8000-000000000001'; b uuid:='70000000-0000-4000-8000-000000000002'; u uuid:='70000000-0000-4000-8000-000000000010'; s uuid:='70000000-0000-4000-8000-000000000030'; p uuid:='70000000-0000-4000-8000-000000000040'; pro uuid:='70000000-0000-4000-8000-000000000012';
BEGIN
 IF NOT EXISTS(SELECT 1 FROM barber.services WHERE id=s) OR NOT EXISTS(SELECT 1 FROM barber.products WHERE id=p) THEN RAISE NOTICE 'Catalog readiness skipped: canonical service/product unavailable'; RETURN; END IF;
END $$;

-- Sprint 58: readiness operacional real, sem confirmar pagamento, estoque ou comissão.
DO $$ DECLARE t uuid:='70000000-0000-4000-8000-000000000001'; b uuid:='70000000-0000-4000-8000-000000000002'; u uuid:='70000000-0000-4000-8000-000000000010'; a uuid; o uuid; c uuid;
BEGIN
 SELECT id,client_id INTO a,c FROM barber.appointments WHERE tenant_id=t AND branch_id=b AND status NOT IN ('Cancelled','NoShow') ORDER BY created_at LIMIT 1;
 IF a IS NULL THEN RAISE NOTICE 'Service execution readiness skipped: appointment unavailable'; RETURN; END IF;
 SELECT id INTO o FROM barber.service_orders WHERE appointment_id=a AND tenant_id=t AND deleted_at IS NULL LIMIT 1;
 IF o IS NULL THEN o:='58580000-0000-4000-8000-000000000001'; INSERT INTO barber.service_orders(id,tenant_id,branch_id,appointment_id,client_id,number,status) VALUES(o,t,b,a,c,'AT-READINESS','Open') ON CONFLICT(id) DO NOTHING; END IF;
 -- allocations, movements, consumption and accrual remain deliberately absent until their real origin event exists.
END $$;
